select `ruphish_event_records`.`id` AS `id`,`ruphish_event_records`.`campaign_id` AS `campaign_id`,`ruphish_event_records`.`email` AS `email`,`ruphish_event_records`.`effective_time` AS `time`,`ruphish_event_records`.`effective_message` AS `message`,`ruphish_event_records`.`effective_details` AS `details`,`ruphish_event_records`.`recipient_id` AS `recipient_id`,`ruphish_event_records`.`source` AS `source`,`ruphish_event_records`.`revision` AS `revision` from `ruphish_event_records` where (`ruphish_event_records`.`excluded` = 0)
